import { useState, useEffect } from 'react';
import { trace, useSnapshot } from '@observatory/lab';

function Clock() {
  const [ticks, setTicks] = useState(0);
  useSnapshot('Clock', { ticks });
  useEffect(() => {
    trace.effect('Clock', 'Подписка создана');
    const timer = setInterval(() => {
      setTicks((n) => n + 1);
      trace.event('Тик подписки');
    }, 700);
    // Что произойдёт с timer при размонтировании?
  }, []);
  return (
    <h1>
      {ticks}
      <small> тиков</small>
    </h1>
  );
}
export default function App() {
  const [visible, setVisible] = useState(true);
  return (
    <section>
      <span className="eyebrow">Жизненный цикл</span>
      {visible ? <Clock /> : <h2>Компонент скрыт</h2>}
      <p>Следите за журналом после выключения часов.</p>
      <button
        onClick={() => {
          trace.action(visible ? 'Скрыть часы' : 'Показать часы');
          setVisible((v) => !v);
        }}
      >
        {visible ? 'Скрыть часы' : 'Показать часы'}
      </button>
    </section>
  );
}

