import { useState } from 'react';
import { trace, useSnapshot } from '@observatory/lab';

const initial = [
  { id: 'a', title: 'Дизайн' },
  { id: 'b', title: 'Разработка' },
  { id: 'c', title: 'Проверка' },
];
function Row({ item }) {
  const [value, setValue] = useState(item.title);
  useSnapshot('Row:' + item.id, {
    id: item.id,
    value,
    title: item.title,
  });
  return (
    <label className="task-row">
      <span>{item.id}</span>
      <input
        aria-label={'Задача ' + item.id}
        value={value}
        onChange={(e) => {
          trace.action('Редактирование', {
            id: item.id,
            value: e.target.value,
          });
          setValue(e.target.value);
        }}
      />
    </label>
  );
}
export default function App() {
  const [items, setItems] = useState(initial);
  return (
    <section>
      <span className="eyebrow">Идентичность</span>
      <h2>План проекта</h2>
      <p>Измените первую задачу и переверните список.</p>
      {items.map((item, index) => (
        <Row key={index} item={item} />
      ))}
      <button
        onClick={() => {
          trace.action('Перевернуть');
          setItems((items) => [...items].reverse());
        }}
      >
        Перевернуть список
      </button>
    </section>
  );
}

