import { useState, memo } from 'react';
import { trace } from '@observatory/lab';

const Chart = memo(function Chart({ data, onSelect }) {
  trace.render('Chart');
  return (
    <div className="chart" onClick={onSelect}>
      {data.map((n, i) => (
        <div key={i} style={{ height: n * 2 + 'px' }} />
      ))}
    </div>
  );
});
export default function App() {
  const [count, setCount] = useState(0);
  trace.render('Dashboard', { count });
  const data = [28, 52, 38, 76, 60];
  const onSelect = () => trace.action('Выбор графика');
  return (
    <section>
      <span className="eyebrow">Стабильные ссылки</span>
      <h2>Аналитика проекта</h2>
      <Chart data={data} onSelect={onSelect} />
      <p>Несвязанное состояние: {count}</p>
      <button
        onClick={() => {
          trace.action('Обновить панель');
          setCount((n) => n + 1);
        }}
      >
        Обновить панель
      </button>
    </section>
  );
}

