import { useState, memo, createContext, useContext } from 'react';
import { trace } from '@observatory/lab';

const UserContext = createContext({ name: 'Алексей', dark: false });

const Profile = memo(function Profile() {
  const user = useContext(UserContext);
  trace.render('Profile');
  return <h2>Привет, {user.name}!</h2>;
});
export default function App() {
  const [dark, setDark] = useState(false);
  trace.render('Provider', { dark });
  const content = (
    <section
      style={{
        background: dark ? '#1e2b45' : '#fff',
        color: dark ? '#fff' : '#182336',
      }}
    >
      <span className="eyebrow">Границы контекста</span>
      <Profile />
      <p>
        Профиль использует только имя. Должна ли тема обновлять профиль?
      </p>
      <button
        onClick={() => {
          trace.action('Сменить тему');
          setDark((v) => !v);
        }}
      >
        Сменить тему
      </button>
    </section>
  );
  return (
    <UserContext.Provider value={{ name: 'Алексей', dark }}>
      {content}
    </UserContext.Provider>
  );
}

