import { useRef } from 'react';
import { trace, useSnapshot } from '@observatory/lab';
import { AbsoluteFill, useCurrentFrame, interpolate } from 'remotion';
import { Player } from '@remotion/player';
function Animation() {
  const frame = useCurrentFrame();
  const opacity = frame < 45 ? 0 : 1;
  useSnapshot('Animation', { frame, opacity });
  return (
    <AbsoluteFill
      style={{
        justifyContent: 'center',
        alignItems: 'center',
        background: '#edf1ff',
      }}
    >
      <div
        style={{
          opacity,
          fontSize: 42,
          color: '#2955e8',
          fontWeight: 700,
        }}
      >
        Привет, кадр!
      </div>
    </AbsoluteFill>
  );
}
export default function App() {
  const player = useRef(null);
  return (
    <section>
      <span className="eyebrow">Время в Remotion</span>
      <h2>Появление заголовка</h2>
      <Player
        ref={player}
        component={Animation}
        durationInFrames={90}
        compositionWidth={600}
        compositionHeight={240}
        fps={30}
        controls
        style={{ width: '100%' }}
      />
      <p>На кадре 30 прозрачность должна быть 0.5.</p>
      <button
        onClick={() => {
          trace.action('Кадр 30');
          player.current?.seekTo(30);
        }}
      >
        Кадр 30
      </button>
    </section>
  );
}

