import { useRef } from 'react';
import { trace, useSnapshot } from '@observatory/lab';
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
} from 'remotion';
import { Player } from '@remotion/player';
function Animation() {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const a = spring({
    frame,
    fps,
    config: { damping: 18, stiffness: 90 },
  });
  const b = spring({
    frame: frame,
    fps,
    config: { damping: 18, stiffness: 90 },
  });
  useSnapshot('Springs', { frame, a, b });
  return (
    <AbsoluteFill
      style={{
        justifyContent: 'center',
        gap: 20,
        padding: 30,
        background: '#edf1ff',
      }}
    >
      {[a, b].map((value, i) => (
        <div
          key={i}
          style={{
            width: value * 85 + 5 + '%',
            height: 32,
            borderRadius: 6,
            background: i ? '#8c74cf' : '#2955e8',
          }}
        />
      ))}
    </AbsoluteFill>
  );
}
export default function App() {
  const player = useRef(null);
  return (
    <section>
      <span className="eyebrow">Хореография</span>
      <h2>Движение с задержкой</h2>
      <Player
        ref={player}
        component={Animation}
        durationInFrames={100}
        compositionWidth={600}
        compositionHeight={240}
        fps={30}
        controls
        style={{ width: '100%' }}
      />
      <p>Второй элемент должен начинать на 12 кадров позже.</p>
      <button
        onClick={() => {
          trace.action('Кадр 18');
          player.current?.seekTo(18);
        }}
      >
        Кадр 18
      </button>
    </section>
  );
}

